namespace MazdaLink.Core;

public static class NativeTransactionPolicy
{
    public const uint KernelAddress=0xFFFF8000, BufferAddress=0xFFFFA000, CommandAddress=0xFFFFA080, StateAddress=0xFFFFA0C0;
    public const string ImageSha256="3ef235e86c0d603f697615e3810580fc9028a2fcb6d83cdba03dfcf89d965ee8";
    public const int ImageLength=2028;
    public const bool HardwareFlashEnabled=false;
    private static readonly byte[] image=Convert.FromHexString("");
    public static byte[] Image
    {
        get { if(image.Length!=ImageLength || RomStorage.Hash(image)!=ImageSha256)throw new InvalidDataException("Native transaction image integrity failed.");return image.ToArray(); }
    }
}
